    .s0_odd_page (tlb_s0_odd_page  ), //i
    .s0_asid     (asid[9:0]        ), //i
    .s0_found    (tlb_s0_found     ), //o
    .s0_ps       (tlb_s0_ps[5:0]   ), //o
    .s0_ppn      (tlb_s0_ppn[19:0] ), //o
