    .w_asid      (asid[9:0]        ), //i
    .w_g         (tlb_w_g          ), //i
    .w_ps        (tlb_w_ps[5:0]    ), //i
    .w_e         (tlb_w_e          ), //i
    .w_v0        (tlb_w_v0         ), //i
    .w_d0        (tlb_w_d0         ), //i
    .w_mat0      (tlb_w_mat0[1:0]  ), //i
